package br.gov.dere.integration.certificate;
import javax.crypto.*; import javax.crypto.spec.*; import java.nio.charset.StandardCharsets; import java.security.*; import java.util.Base64;
public class PocSecretBox { private final byte[] key; public PocSecretBox(String raw){try{key=MessageDigest.getInstance("SHA-256").digest(raw.getBytes(StandardCharsets.UTF_8));}catch(Exception e){throw new IllegalStateException(e);}} public String encrypt(String value)throws Exception{return Base64.getEncoder().encodeToString(crypt(Cipher.ENCRYPT_MODE,value.getBytes(StandardCharsets.UTF_8)));} public String decrypt(String value)throws Exception{return new String(crypt(Cipher.DECRYPT_MODE,Base64.getDecoder().decode(value)),StandardCharsets.UTF_8);} public byte[] encrypt(byte[] value)throws Exception{return crypt(Cipher.ENCRYPT_MODE,value);} public byte[] decrypt(byte[] value)throws Exception{return crypt(Cipher.DECRYPT_MODE,value);} private byte[] crypt(int mode,byte[] value)throws Exception{var iv=new byte[12];if(mode==Cipher.ENCRYPT_MODE)new SecureRandom().nextBytes(iv);else{var all=value;iv=java.util.Arrays.copyOf(all,12);value=java.util.Arrays.copyOfRange(all,12,all.length);}var c=Cipher.getInstance("AES/GCM/NoPadding");c.init(mode,new SecretKeySpec(key,"AES"),new GCMParameterSpec(128,iv));var out=c.doFinal(value);if(mode==Cipher.ENCRYPT_MODE){var all=new byte[iv.length+out.length];System.arraycopy(iv,0,all,0,iv.length);System.arraycopy(out,0,all,iv.length,out.length);return all;}return out;} }
